'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}), uid=()=>crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2), KEY='classdesk-v1';
const isDemo=new URLSearchParams(location.search).get('mode')==='demo';
function blankClass(settings={}){let value=demo();for(let k of Object.keys(value))if(Array.isArray(value[k]))value[k]=[];value.seat.ids=[];value.settings={...value.settings,teacher:'老师',className:'我的班级',...settings};return value;}
const names=['陈子墨','林沐阳','王语桐','李思远','张梓涵','刘一诺','赵星辰','周雨晴','吴宇航','徐诗涵','孙浩然','朱可欣','马嘉树','胡芷萱','郭奕辰','何欣怡','高明轩','罗安然','郑睿哲','梁若溪','谢景行','宋依琳','唐沐宸','许梦琪','邓书航','冯悦宁','韩知远','曹清妍','曾承泽','彭雅宁','萧云帆','程乐言','袁亦晨','潘念初','董嘉言','蔡予安'];
function demo(){let students=names.map((name,i)=>({id:'s'+i,name,gender:i%2?'女':'男',number:String(i+1).padStart(2,'0'),phone:'1380000'+String(1000+i),height:148+(i*7%30),myopia:i%7===0,front:i===4,pet:['cat','dog','rabbit'][i%3],points:50+i%6*5,xp:i%5*18,food:80,mood:90,clean:85,decor:'',evaluation:''}));let exams=['9月摸底考试','10月月考'].map((title,j)=>({id:'e'+j,title,date:j?'2026-10-20':'2026-09-12',scores:students.map((s,i)=>({student:s.id,语文:65+(i*7+j*3)%31,数学:61+(i*11+j*5)%39,英语:68+(i*9+j*2)%32}))}));return {version:1,settings:{teacher:'林老师',className:'初二（3）班',term:'2026—2027 学年 · 第一学期',pass:60,excellent:85},students,exams,discipline:[{id:'d1',student:'s4',date:today(),type:'课堂纪律',reason:'课堂交头接耳',follow:'课后沟通，观察后续表现'},{id:'d2',student:'s8',date:today(),type:'迟到',reason:'早读迟到',follow:'提醒提前出门'}],leaves:[{id:'l1',student:'s2',date:today(),end:today(),type:'病假',reason:'身体不适',status:'已批准',photo:''},{id:'l2',student:'s11',date:today(),end:today(),type:'事假',reason:'家庭事务',status:'待审批',photo:''}],homework:[{id:'h1',subject:'数学',title:'一次函数 · 课后练习',date:today(),deadline:today(),submitted:students.filter((s,i)=>i%13!==0).map(s=>s.id)},{id:'h2',subject:'语文',title:'《背影》阅读与赏析',date:today(),deadline:today(),submitted:students.filter((s,i)=>i%17!==0).map(s=>s.id)},{id:'h3',subject:'英语',title:'Unit 4 词汇与阅读',date:today(),deadline:today(),submitted:students.filter((s,i)=>i%7!==0).map(s=>s.id)}],work:[{id:'w1',date:today(),title:'秋季安全教育主题班会',type:'主题班会',place:'本班教室',content:'围绕校园安全与课间活动规范开展交流。',photo:''}],talks:[{id:'t1',student:'s4',date:today(),type:'学业',title:'近期学习状态交流',content:'了解学生近期作业完成和课堂专注情况。',measure:'共同制定本周学习小目标。',response:'愿意尝试按计划完成。',plan:'周五课后回访。',recorder:'林老师'}],contacts:[],activities:[{id:'a1',date:today(),title:'秋季运动会',type:'班级活动',content:'整理报名名单与后勤安排。'}],todos:[{id:'b1',title:'整理本月家校沟通记录',date:today(),important:true,done:false},{id:'b2',title:'提醒收齐运动会报名表',date:today(),important:true,done:false},{id:'b3',title:'跟进请假学生的学习情况',date:today(),important:false,done:false},{id:'b4',title:'完成安全教育主题班会',date:today(),important:false,done:true}],notes:[],links:[{id:'u1',title:'国家中小学智慧教育平台',url:'https://basic.smartedu.cn'},{id:'u2',title:'中华人民共和国教育部',url:'https://www.moe.gov.cn'}],points:[],seat:{rows:6,cols:6,aisle:3,ids:students.map(s=>s.id)},seatHistory:[]};}
let db;try{if(isDemo){db=demo()}else{let setup=sessionStorage.getItem('classdesk-setup');db=JSON.parse(localStorage.getItem(KEY))||blankClass(setup?JSON.parse(setup):{});sessionStorage.removeItem('classdesk-setup')}}catch{db=isDemo?demo():blankClass()}let page='dashboard',tab='',query='',selectedSeat=null,filterStudent='',examId=db.exams.at(-1)?.id||'',petFilter='';
function save(){if(isDemo){$('#saved').textContent='演示模式 · 不保存';return true}try{localStorage.setItem(KEY,JSON.stringify(db));$('#saved').innerHTML='<span class="dot"></span> 已自动保存';return true}catch{$('#saved').textContent='保存失败';toast('存储空间不足，请导出备份后减少照片');return false}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastT);window.toastT=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
const icon=n=>`<i data-lucide="${n}"></i>`, btn=(text,fn,ico='',cls='')=>`<button class="btn ${cls}" onclick="${fn}">${ico?icon(ico):''}${text}</button>`, sn=id=>db.students.find(s=>s.id===id)?.name||'已移除学生', studentOptions=()=>db.students.map(s=>`<option value="${s.id}">${esc(s.number)} · ${esc(s.name)}</option>`).join(''), panel=(title,body,action='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div>${body}</section>`, empty=(s='暂无记录')=>`<div class="empty">${icon('inbox')}${s}</div>`;
const menus=[['dashboard','layout-dashboard','仪表盘'],['students','users-round','学生管理'],['grades','chart-no-axes-combined','成绩分析'],['discipline','shield-alert','违纪统计'],['homework','notebook-pen','作业管理'],['leaves','calendar-clock','请假管理'],['work','folder-open','工作留痕'],['talks','messages-square','谈话记录'],['seats','armchair','排座位'],['contacts','contact-round','家校沟通'],['activities','flag','班级活动'],['pets','paw-print','成长乐园'],['todo','list-checks','待办 & 备忘录'],['links','link','常用网址']];
function icons(){lucide.createIcons()}
function nav(){ $('#sidebar').innerHTML=`<div class="brand"><span class="brand-mark">${icon('sprout')}</span><span class="brand-text">班主任工作台</span></div><div class="class-profile"><div class="row"><span class="teacher-avatar">${esc(db.settings.teacher[0])}</span><div><strong>${esc(db.settings.className)}</strong><small>${esc(db.settings.teacher)} · ${db.students.length} 位学生</small></div></div></div><div class="nav-scroll"><div class="nav-label">班级日常</div>${menus.map((m,i)=>`${i===11?'<div class="nav-label">成长与工具</div>':''}<button class="nav-item ${page===m[0]?'active':''}" onclick="go('${m[0]}')">${icon(m[1])}<span class="nav-text">${m[2]}</span>${m[0]==='todo'&&db.todos.some(t=>!t.done)?`<span class="badge">${db.todos.filter(t=>!t.done).length}</span>`:''}</button>`).join('')}</div><button class="sidebar-growth" onclick="go('pets')"><span>让每一点进步<br>都被看见</span><span class="growth-stars">✦ ✦ ✦</span><span class="growth-link">成长乐园 ↗</span></button><div class="nav-bottom">${[['data','database-backup','数据管理'],['settings','settings-2','系统设置']].map(m=>`<button class="nav-item ${page===m[0]?'active':''}" onclick="go('${m[0]}')">${icon(m[1])}<span class="nav-text">${m[2]}</span></button>`).join('')}<button class="nav-item" onclick="document.body.classList.toggle('collapsed')">${icon('panel-left-close')}<span class="nav-text">收起侧栏</span></button></div>`;}
function go(p,t=''){page=p;tab=t;query='';filterStudent='';document.body.classList.remove('nav-open');render();window.scrollTo(0,0)}
function head(title,actions='',sub=''){return `<div class="page-head"><div><h1>${title}</h1>${sub?`<div class="subtitle">${sub}</div>`:''}</div><div class="actions">${actions}</div></div>`}
function tabs(items){if(!items.some(x=>x[0]===tab))tab=items[0][0];return `<div class="tabs">${items.map(([v,l])=>`<button class="tab ${tab===v?'active':''}" onclick="tab='${v}';query='';render()">${l}</button>`).join('')}</div>`}
function stat(label,value,note='',ico=''){return `<div class="stat"><div class="label">${label}${ico?icon(ico):''}</div><div class="value">${value}</div><div class="note">${note}</div></div>`}
function latest(){return db.exams.find(e=>e.id===examId)||db.exams.at(-1)}const subjects=['语文','数学','英语'];
function avg(ex,sub){let a=(ex?.scores||[]).map(s=>+s[sub]).filter(Number.isFinite);return a.length?a.reduce((a,b)=>a+b,0)/a.length:0}
function bars(data,max=100){return `<div class="bars">${data.map(([l,v],i)=>`<div class="bar-row"><b>${esc(l)}</b><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,v/max*100)}%;background:${['#785bfa','#a997f7','#bfc1ed','#9c85dc','#d2c5f4'][i%5]}"></div></div><em>${Number(v.toFixed(1))}</em></div>`).join('')}</div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">${empty()}</td></tr>`}</tbody></table></div>`}
function operations(collection,id,word=false){return `<div class="actions">${btn('编辑',`edit('${collection}','${id}')`,'','small')}${word?btn('Word',`wordRecord('${collection}','${id}')`,'','small'):''}<button class="icon" aria-label="删除" onclick="removeRecord('${collection}','${id}')">${icon('trash-2')}</button></div>`}
function searchBar(extra=''){return `<div class="toolbar"><label class="search">${icon('search')}<input aria-label="搜索" value="${esc(query)}" placeholder="搜索姓名或关键词" oninput="query=this.value;renderContent(true)"></label><div class="actions">${extra}</div></div>`}
function renderContent(focus=false){let pos=focus?$('input[aria-label="搜索"]')?.selectionStart:null;$('#main').innerHTML=views[page]();icons();if(focus){let el=$('input[aria-label="搜索"]');el?.focus();if(pos!=null)el?.setSelectionRange(pos,pos)}}
function render(){nav();$('#bread').textContent=`${db.settings.teacher}的班主任工作台 / ${menus.find(m=>m[0]===page)?.[2]||({data:'数据管理',settings:'系统设置'}[page])}`;$('.avatar').textContent=db.settings.teacher[0];renderContent();icons()}
function todoList(limit){return db.todos.slice(0,limit).map(t=>`<div class="todo-item ${t.done?'done':''}"><input type="checkbox" aria-label="完成${esc(t.title)}" ${t.done?'checked':''} onchange="toggleTodo('${t.id}')"><span class="text">${esc(t.title)}</span>${t.important&&!t.done?'<span class="pill orange">重要</span>':''}${page==='todo'?operations('todos',t.id):''}</div>`).join('')||empty('今日暂无待办')}
const views={};
function percent(h){let n=h.submitted.filter(id=>db.students.some(s=>s.id===id)).length;return db.students.length?Math.round(n/db.students.length*100):0}
views.students=()=>head('学生管理',btn('导入',"importData('students')",'upload')+btn('导出 Excel',"exportData('students')",'download')+btn('添加学生',"edit('students')",'plus','primary'),`${db.students.length} 位学生`)+panel('学生花名册',searchBar(btn('下载模板',"template('students')",'file-down'))+table(['学号','学生姓名','性别','家长电话','近期记录','操作'],db.students.filter(s=>(s.name+s.number+s.phone).includes(query)).map(s=>[esc(s.number),`<button class="name-btn" onclick="profile('${s.id}')"><span class="student-icon">${esc(s.name.slice(-2))}</span>${esc(s.name)}</button>`,esc(s.gender),esc(s.phone),`<span class="pill">请假 ${db.leaves.filter(x=>x.student===s.id).length}</span> <span class="pill ${db.discipline.some(x=>x.student===s.id)?'orange':''}">违纪 ${db.discipline.filter(x=>x.student===s.id).length}</span>`,operations('students',s.id)])));
function profile(id){let s=db.students.find(s=>s.id===id);let ex=latest();let score=ex?.scores.find(x=>x.student===id);let b=`<div class="profile-top"><span class="student-icon">${esc(s.name.slice(-2))}</span><div><h1>${esc(s.name)}</h1><small>${esc(s.number)} 号 · ${esc(s.gender)} · ${esc(db.settings.className)}</small></div></div><div class="metric4">${stat('最近总分',score?subjects.reduce((n,k)=>n+(+score[k]||0),0):'—')}${stat('请假记录',db.leaves.filter(x=>x.student===id).length)}${stat('违纪记录',db.discipline.filter(x=>x.student===id).length)}${stat('作业完成',db.homework.filter(x=>x.submitted.includes(id)).length+'/'+db.homework.length)}</div><div class="divider"></div><h3>成绩概览</h3>${bars(subjects.map(k=>[k,Number(score?.[k])||0]))}<div class="divider"></div><h3>综合评价</h3><p class="record-content">${esc(s.evaluation||'暂无评价')}</p><h3>最近记录</h3>${[...db.talks,...db.discipline,...db.leaves].filter(x=>x.student===id).map(x=>`<p class="record-content">${x.date} · ${esc(x.type)} · ${esc(x.title||x.reason||'')}</p>`).join('')||empty()}`;showModal('学生个人档案',b,btn('导出个人报告',`studentWord('${id}')`,'file-down','primary'),true)}
views.grades=()=>{let ts=tabs([['exams','考试列表'],['entry','成绩录入'],['analysis','单次分析'],['trend','个人趋势'],['change','进退步'],['ranking','班级排名']]);let ex=latest();let selector=`<select aria-label="考试" onchange="examId=this.value;render()">${db.exams.map(e=>`<option value="${e.id}" ${e.id===ex?.id?'selected':''}>${esc(e.title)}</option>`).join('')}</select>`;let content='';if(tab==='exams')content=`<div class="card-grid">${db.exams.map(e=>`<section class="panel"><span class="pill">${e.date}</span><h2 style="margin:20px 0 10px">${esc(e.title)}</h2><p class="muted">${e.scores.length} 人 · ${subjects.length} 科</p><div class="actions">${btn('查看分析',`examId='${e.id}';tab='analysis';render()`,'chart-column','primary')}${operations('exams',e.id)}</div></section>`).join('')}</div>`;else if(!ex)content=empty('请先新增考试');else if(tab==='entry')content=panel('成绩录入',`<div class="toolbar">${selector}<div class="actions">${btn('导入 Excel',"importData('scores')",'upload')}${btn('下载模板',"template('scores')",'file-down')}${btn('保存成绩',"saveScores()",'check','primary')}</div></div>`+table(['学号','姓名',...subjects],db.students.map(s=>[esc(s.number),esc(s.name),...subjects.map(k=>`<input style="width:85px" type="number" min="0" max="100" aria-label="${esc(s.name+k)}" data-score="${s.id}" data-sub="${k}" value="${ex.scores.find(r=>r.student===s.id)?.[k]??''}">`)])));else if(tab==='analysis'){content=`<div class="toolbar">${selector}${btn('导出 Excel',"exportData('scores')",'download')}</div><div class="grid3">${subjects.map(k=>{let a=ex.scores.map(x=>+x[k]).filter(Number.isFinite);return panel(k,`<div style="font:35px Georgia;margin:18px 0">${avg(ex,k).toFixed(1)} <small style="font:11px sans-serif">平均分</small></div><div class="row" style="font-size:11px">最高 ${a.length?Math.max(...a):'—'}　最低 ${a.length?Math.min(...a):'—'}</div><p class="muted" style="font-size:11px">及格率 ${a.length?Math.round(a.filter(v=>v>=db.settings.pass).length/a.length*100):0}%　优秀率 ${a.length?Math.round(a.filter(v=>v>=db.settings.excellent).length/a.length*100):0}%</p>`)}).join('')}</div><div class="grid2">${panel('各科平均分',bars(subjects.map(k=>[k,avg(ex,k)])))}${panel('总分分布',bars([['270–300',ex.scores.filter(s=>total(s)>=270).length],['240–269',ex.scores.filter(s=>total(s)>=240&&total(s)<270).length],['180–239',ex.scores.filter(s=>total(s)>=180&&total(s)<240).length],['180以下',ex.scores.filter(s=>total(s)<180).length]],Math.max(1,ex.scores.length)))}</div>`}else if(tab==='trend'){let s=filterStudent||db.students[0]?.id;content=panel('个人成绩趋势',`<select onchange="filterStudent=this.value;render()">${db.students.map(x=>`<option value="${x.id}" ${s===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`+lineChart(db.exams.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(e=>[e.title,...subjects.map(k=>Number(e.scores.find(r=>r.student===s)?.[k])||0)]),subjects))}else if(tab==='change'){let es=db.exams.slice().sort((a,b)=>a.date.localeCompare(b.date));let cur=es.at(-1),prev=es.at(-2);if(!prev)content=empty('至少需要两次考试');else{let curranks=ranking(cur),pranks=ranking(prev);let diff=curranks.filter(r=>pranks.some(p=>p.student===r.student)).map(r=>[sn(r.student),pranks.find(p=>p.student===r.student).rank-r.rank]);content=panel('进退步分析',`<p class="muted">${esc(prev.title)} → ${esc(cur.title)} · 按总分排名变化</p><div class="grid2">${panel('进步 TOP 5',bars(diff.filter(d=>d[1]>0).sort((a,b)=>b[1]-a[1]).slice(0,5),db.students.length))}${panel('退步 TOP 5',bars(diff.filter(d=>d[1]<0).sort((a,b)=>a[1]-b[1]).slice(0,5).map(([n,d])=>[n,-d]),db.students.length))}</div>`)}}else content=panel('班级排名总表',`<div class="toolbar">${selector}${btn('导出 Excel',"exportData('scores')",'download')}</div>`+table(['排名','姓名',...subjects,'总分'],ranking(ex).map(r=>[r.rank,esc(sn(r.student)),...subjects.map(k=>r[k]),total(r)])));return head('成绩分析',btn('新增考试',"edit('exams')",'plus','primary'))+ts+content};
const total=s=>subjects.reduce((n,k)=>n+(Number(s[k])||0),0);function ranking(ex){let a=(ex?.scores||[]).filter(s=>db.students.some(x=>x.id===s.student)).slice().sort((a,b)=>total(b)-total(a));return a.map((r,i)=>({...r,rank:i&&total(r)===total(a[i-1])?a.findIndex(x=>total(x)===total(r))+1:i+1}))}
function saveScores(){let ex=latest(),map=new Map();document.querySelectorAll('[data-score]').forEach(i=>{if(i.value==='')return;let v=+i.value;if(!Number.isFinite(v)||v<0||v>100)throw new Error('成绩须在0–100之间');if(!map.has(i.dataset.score))map.set(i.dataset.score,{student:i.dataset.score});map.get(i.dataset.score)[i.dataset.sub]=v});if([...map.values()].some(r=>subjects.some(k=>r[k]==null))){toast('请将该学生的三科成绩填写完整');return}ex.scores=[...map.values()];save();toast('成绩已保存');render()}
function lineChart(rows,series){if(!rows.length)return empty();let colors=['#785bfa','#b497f3','#8bb4d5'];let w=650,h=210;return `<svg class="svgline" viewBox="0 0 700 260" role="img" aria-label="成绩趋势图">${[0,20,40,60,80,100].map(v=>`<line x1="35" y1="${220-v*1.8}" x2="675" y2="${220-v*1.8}" stroke="#e9eee5"/><text x="5" y="${224-v*1.8}" fill="#9ba697" font-size="10">${v}</text>`).join('')}${series.map((s,j)=>`<polyline fill="none" stroke="${colors[j]}" stroke-width="2.5" points="${rows.map((r,i)=>`${50+i*(600/Math.max(1,rows.length-1))},${220-r[j+1]*1.8}`).join(' ')}"/>${rows.map((r,i)=>`<circle cx="${50+i*(600/Math.max(1,rows.length-1))}" cy="${220-r[j+1]*1.8}" r="4" fill="${colors[j]}"><title>${esc(r[0])} ${s} ${r[j+1]}</title></circle>`).join('')}`).join('')}${rows.map((r,i)=>`<text x="${50+i*600/Math.max(1,rows.length-1)}" y="245" text-anchor="middle" fill="#899b88" font-size="11">${esc(r[0])}</text>`).join('')}</svg><div class="row" style="justify-content:center;font-size:11px">${series.map((s,i)=>`<span style="color:${colors[i]}">● ${s}</span>`).join('')}</div>`}
const schemas={students:[['number','学号'],['name','姓名'],['gender','性别','select',['男','女']],['phone','家长电话'],['height','身高（cm）','number'],['myopia','近视','check'],['front','优先前三排','check'],['evaluation','综合评价','textarea']],discipline:[['student','学生','student'],['date','日期','date'],['type','类型','select',['课堂纪律','迟到','行为规范','其他']],['reason','事由','textarea'],['follow','教育措施','textarea']],leaves:[['student','学生','student'],['date','开始日期','date'],['end','结束日期','date'],['type','类型','select',['病假','事假','其他']],['reason','请假原因','textarea'],['status','审批状态','select',['待审批','已批准','已拒绝']],['photo','凭证图片','file']],homework:[['subject','科目','select',subjects],['title','作业标题'],['date','布置日期','date'],['deadline','截止日期','date']],work:[['date','日期','date'],['title','工作标题'],['type','类型','select',['主题班会','家校沟通','安全巡查','学业辅导','活动组织']],['place','地点'],['content','工作内容','textarea'],['photo','照片','file']],talks:[['student','学生','student'],['date','日期','date'],['type','类型','select',['心理','学业','纪律','家校','其他']],['title','简要事由'],['recorder','记录人'],['content','谈话内容','textarea'],['measure','教育疏导措施','textarea'],['response','学生表态','textarea'],['plan','跟进计划','textarea']],contacts:[['student','学生','student'],['date','日期','date'],['type','类型','select',['家访记录','家长会记录','家长群通知','日常沟通']],['title','主题'],['content','沟通内容','textarea'],['plan','跟进计划','textarea']],activities:[['date','日期','date'],['title','标题'],['type','类型','select',['班会记录','班级活动','获奖记录','值日安排','班干部安排']],['content','内容','textarea'],['photo','照片','file']],todos:[['title','待办事项'],['date','提醒日期','date'],['important','重要事项','check']],notes:[['title','笔记标题'],['content','笔记内容','textarea']],links:[['title','网站名称'],['url','网址','url']],exams:[['title','考试名称'],['date','考试日期','date']]};
const collectionNames={students:'学生',discipline:'违纪记录',leaves:'请假记录',homework:'作业',work:'工作记录',talks:'谈话记录',contacts:'家校沟通',activities:'班级活动',todos:'待办',notes:'备忘录',links:'常用网址',exams:'考试'};
function field([key,label,type,options],value=''){return `<label class="field ${['textarea','file'].includes(type)?'full':''}"><span>${label}</span>${type==='textarea'?`<textarea name="${key}">${esc(value)}</textarea>`:type==='select'||type==='student'?`<select name="${key}">${type==='student'?studentOptions():options.map(v=>`<option ${v===value?'selected':''}>${v}</option>`).join('')}</select>`:type==='check'?`<input type="checkbox" name="${key}" ${value?'checked':''} style="width:17px;accent-color:#7858fa">`:`<input name="${key}" ${type==='file'?'accept="image/*"':''} type="${type||'text'}" ${type==='file'?'':`value="${esc(value)}"`} ${['name','number','title','date','end','deadline','url','height'].includes(key)?'required':''} ${type==='number'?'min="0" max="250"':''}>`}</label>`}
function showModal(title,body,foot='',wide=false){$('#modal').innerHTML=`<div class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="dialog-head"><h2>${esc(title)}</h2><button class="icon" aria-label="关闭" onclick="closeModal()">${icon('x')}</button></div><div class="dialog-body">${body}</div>${foot?`<div class="dialog-foot">${foot}</div>`:''}</div>`;$('#modal').hidden=false;icons();$('#modal input, #modal textarea, #modal button')?.focus()}
function closeModal(){$('#modal').hidden=true}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});
function edit(col,id){if(['discipline','leaves','talks','contacts'].includes(col)&&!db.students.length){toast('请先添加学生');return}let r=db[col].find(x=>x.id===id)||{};let vals={date:today(),end:today(),deadline:today(),height:160,recorder:db.settings.teacher,...r};showModal((id?'编辑':'新增')+collectionNames[col],`<form id="edit-form" class="form-grid" onsubmit="event.preventDefault();submitRecord('${col}','${id||''}')">${schemas[col].map(s=>field(s,vals[s[0]])).join('')}<button hidden type="submit"></button></form>`,btn('取消',"closeModal()")+`<button class="btn primary" form="edit-form" type="submit">保存</button>`);if(r.student)$('#edit-form [name=student]').value=r.student}
async function submitRecord(col,id){let form=$('#edit-form');if(!form.reportValidity())return;let fd=new FormData(form);let existing=db[col].find(x=>x.id===id);let rec={...(existing||{}),id:id||uid()};for(let [k,l,t]of schemas[col]){if(t==='file'){let f=fd.get(k);if(f?.size){rec[k]=await readPhoto(f)}}else rec[k]=t==='check'?fd.has(k):t==='number'?+fd.get(k):String(fd.get(k)||'').trim()};if(rec.date&&rec.end&&rec.end<rec.date){toast('结束日期不能早于开始日期');return}if(rec.deadline&&rec.deadline<rec.date){toast('截止日期不能早于布置日期');return}if(col==='links'&&!/^https?:\/\//i.test(rec.url)){toast('网址须以 https:// 或 http:// 开头');return}if(col==='students'){if(db.students.some(s=>s.number===rec.number&&s.id!==id)){toast('学号重复，请检查');return}if(!existing)Object.assign(rec,{pet:'cat',points:0,xp:0,food:80,mood:80,clean:80,decor:''})}if(col==='exams'&&!existing)rec.scores=[];if(col==='homework'&&!existing)rec.submitted=[];if(col==='todos'&&!existing)rec.done=false;if(existing)Object.assign(existing,rec);else db[col].push(rec);if(save()){closeModal();render();toast('已保存')}}
function readPhoto(f){return new Promise((resolve,reject)=>{let r=new FileReader;r.onload=()=>{let im=new Image;im.onload=()=>{let c=document.createElement('canvas');let scale=Math.min(1,1200/Math.max(im.width,im.height));c.width=im.width*scale;c.height=im.height*scale;c.getContext('2d').drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.75))};im.src=r.result};r.onerror=reject;r.readAsDataURL(f)})}
function removeRecord(col,id){showModal('删除确认',`<p>确定删除这条${collectionNames[col]||'记录'}？${col==='students'?'该学生的成绩、请假、作业及相关记录也会一并移除。':''}</p>`,btn('取消','closeModal()')+btn('确认删除',`doRemove('${col}','${id}')`,'trash-2','danger'))}
function doRemove(col,id){db[col]=db[col].filter(x=>x.id!==id);if(col==='students'){for(let k of ['discipline','leaves','talks','contacts','points'])db[k]=db[k].filter(x=>x.student!==id);db.exams.forEach(e=>e.scores=e.scores.filter(x=>x.student!==id));db.homework.forEach(h=>h.submitted=h.submitted.filter(x=>x!==id));db.seat.ids=db.seat.ids.map(x=>x===id?null:x)}save();closeModal();render();toast('已删除')}
function toggleTodo(id){let t=db.todos.find(t=>t.id===id);t.done=!t.done;save();render()}
function typeCounts(col){let m={};db[col].forEach(r=>m[r.type]=(m[r.type]||0)+1);return Object.entries(m)}
function donut(data){let sum=data.reduce((s,x)=>s+x[1],0),n=0,colors=['#785bfa','#a697ed','#cdc4fa','#a4badb','#e3d9fa'];let gradient=data.map(([k,v],i)=>{let start=n;n+=v/(sum||1)*100;return `${colors[i%5]} ${start}% ${n}%`}).join(',');return `<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${gradient||'#e9eee5 0% 100%'})"><div class="donut-text">${sum}<small>总次数</small></div></div><div>${data.map(([k,v],i)=>`<div class="key-row"><span style="background:${colors[i%5]}"></span>${esc(k)}　${v}</div>`).join('')}</div></div>`}
views.discipline=()=>{let count=typeCounts('discipline');let students=db.students.map(s=>[s.name,db.discipline.filter(r=>r.student===s.id).length]).filter(r=>r[1]).sort((a,b)=>b[1]-a[1]);return head('违纪统计',btn('导出 Excel',"exportData('discipline')",'download')+btn('新增记录',"edit('discipline')",'plus','primary'))+`<div class="stats" style="grid-template-columns:repeat(4,1fr)">${stat('本月记录',db.discipline.filter(r=>r.date.startsWith(today().slice(0,7))).length)}${stat('最常见类型',`<span style="font-size:16px;margin:0">${esc(count.sort((a,b)=>b[1]-a[1])[0]?.[0]||'—')}</span>`)}${stat('涉及学生',new Set(db.discipline.map(r=>r.student)).size)}${stat('近30天记录',db.discipline.filter(r=>dayDiff(r.date)<=30&&dayDiff(r.date)>=0).length)}</div><div class="grid2">${panel('违纪类型',donut(count))}${panel('次数 TOP 5',bars(students.slice(0,5),Math.max(1,...students.map(x=>x[1]))))}</div>${panel('近30天趋势',dailyChart('discipline'))}`+recordsPanel('discipline')};
function dayDiff(date){return (new Date(today())-new Date(date))/86400000}
function dailyChart(col){let rows=Array.from({length:30},(_,i)=>{let d=new Date(today());d.setDate(d.getDate()-29+i);let date=d.toLocaleDateString('sv-SE');return [date.slice(5),db[col].filter(r=>r.date===date).length]});let max=Math.max(1,...rows.map(x=>x[1]));return `<svg viewBox="0 0 700 160" style="width:100%;height:150px"><line x1="10" y1="130" x2="690" y2="130" stroke="#e5ebe0"/>${rows.map(([l,n],i)=>`<rect x="${12+i*22.5}" y="${130-n/max*105}" width="12" height="${Math.max(2,n/max*105)}" rx="2" fill="#9f8de8"><title>${l}：${n}次</title></rect>${i%5===0?`<text x="${12+i*22.5}" y="152" font-size="10" fill="#8d9a86">${l}</text>`:''}`).join('')}</svg>`}
function recordsPanel(col){let schema=schemas[col].filter(([k,l,t])=>!['textarea','file','check'].includes(t));let rows=db[col].filter(r=>(Object.values(r).join(' ')+sn(r.student)).includes(query)).filter(r=>!filterStudent||r.student===filterStudent).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return panel(collectionNames[col]+'列表',searchBar(['talks','contacts','leaves','discipline'].includes(col)?`<select onchange="filterStudent=this.value;render()"><option value="">全部学生</option>${db.students.map(s=>`<option value="${s.id}" ${filterStudent===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`:'')+table([...schema.map(s=>s[1]),'操作'],rows.map(r=>[...schema.map(([k,l,t])=>k==='student'?`<button class="name-btn" onclick="profile('${r.student}')">${esc(sn(r.student))}</button>`:k==='status'?`<span class="pill ${r.status==='待审批'?'orange':''}">${esc(r[k])}</span>`:esc(r[k])),`<div class="actions">${btn('查看',`detail('${col}','${r.id}')`,'','small')}${operations(col,r.id,true)}</div>`])))}
function detail(col,id){let r=db[col].find(r=>r.id===id);showModal(collectionNames[col],schemas[col].map(([k,l,t])=>`<div style="margin-bottom:18px"><small>${l}</small>${t==='file'?r[k]?`<div class="photos"><img src="${r[k]}" alt="凭证照片"></div>`:'<p>—</p>':`<div class="record-content">${esc(k==='student'?sn(r[k]):r[k]||'—')}</div>`}</div>`).join(''),btn('导出 Word',`wordRecord('${col}','${id}')`,'download','primary'))}
views.leaves=()=>head('请假管理',btn('导出 Excel',"exportData('leaves')",'download')+btn('请假登记',"edit('leaves')",'plus','primary'))+`<div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat('今日请假',db.leaves.filter(r=>r.date<=today()&&r.end>=today()&&r.status==='已批准').length)}${stat('待审批',db.leaves.filter(r=>r.status==='待审批').length)}${stat('本月请假',db.leaves.filter(r=>r.date.startsWith(today().slice(0,7))).length)}</div>`+recordsPanel('leaves');
views.homework=()=>{let ts=tabs([['list','作业列表'],['stats','统计看板']]);return head('作业管理',btn('导出 Excel',"exportData('homework')",'download')+btn('布置作业',"edit('homework')",'plus','primary'))+ts+(tab==='list'?panel('作业列表',searchBar()+table(['科目','作业标题','布置日期','截止日期','提交率','操作'],db.homework.filter(h=>(h.title+h.subject).includes(query)).map(h=>[`<span class="pill">${esc(h.subject)}</span>`,esc(h.title),h.date,h.deadline,`${percent(h)}%`,`${btn('完成情况',`homeworkDetail('${h.id}')`,'','small')}${operations('homework',h.id)}`]))):`<div class="grid2">${panel('各项作业提交率',bars(db.homework.map(h=>[h.subject+' · '+h.title,percent(h)])))}${panel('待交统计',table(['姓名','未交次数'],db.students.map(s=>[s.name,db.homework.filter(h=>!h.submitted.includes(s.id)).length]).filter(r=>r[1]).sort((a,b)=>b[1]-a[1]).map(r=>[esc(r[0]),r[1]])))}</div>`)};
function homeworkDetail(id){let h=db.homework.find(x=>x.id===id);showModal(h.title,`<div class="toolbar"><span>已交 ${h.submitted.filter(id=>db.students.some(s=>s.id===id)).length} / ${db.students.length}</span>${btn('全部已交',`allSubmitted('${id}')`,'check-check')}</div><div class="homework-tiles">${db.students.map(s=>`<button class="student-tile ${h.submitted.includes(s.id)?'':'missing'}" onclick="toggleSubmitted('${id}','${s.id}')">${esc(s.name)}<br><small>${h.submitted.includes(s.id)?'已提交':'未提交'}</small></button>`).join('')}</div>`,btn('完成','closeModal();render()','','primary'),true)}
function toggleSubmitted(hid,sid){let h=db.homework.find(h=>h.id===hid);h.submitted=h.submitted.includes(sid)?h.submitted.filter(x=>x!==sid):[...h.submitted,sid];save();homeworkDetail(hid)}function allSubmitted(id){db.homework.find(h=>h.id===id).submitted=db.students.map(s=>s.id);save();homeworkDetail(id)}
views.work=()=>{let ts=tabs([['list','工作列表'],['timeline','时间轴'],['stats','统计概览']]);let content=tab==='list'?recordsPanel('work'):tab==='timeline'?panel('工作时间轴',`<div class="timeline">${db.work.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<article><small>${r.date} · ${esc(r.type)}</small><h3 style="margin-top:10px">${esc(r.title)}</h3><p>${esc(r.content)}</p>${r.photo?`<div class="photos"><img src="${r.photo}" alt="工作照片"></div>`:''}${btn('查看',`detail('work','${r.id}')`,'','small')}</article>`).join('')}</div>`):`<div class="grid2">${panel('本学期工作类型',donut(typeCounts('work')))}${panel('近六个月工作趋势',bars(Array.from({length:6},(_,i)=>{let d=new Date();d.setMonth(d.getMonth()-5+i);let m=d.toLocaleDateString('sv-SE').slice(0,7);return [m,db.work.filter(w=>w.date.startsWith(m)).length]}),Math.max(1,db.work.length)))}</div>`;return head('工作留痕',btn('Excel',"exportData('work')",'download')+btn('批量 Word',"wordAll('work')",'files')+btn('新增工作',"edit('work')",'plus','primary'))+ts+content};
views.talks=()=>head('谈话记录',btn('按学生 Word',"wordFiltered('talks')",'file-down')+btn('全部 Word',"wordAll('talks')",'files')+btn('新增谈话',"edit('talks')",'plus','primary'))+recordsPanel('talks');
views.contacts=()=>head('家校沟通',btn('导出 Excel',"exportData('contacts')",'download')+btn('新增记录',"edit('contacts')",'plus','primary'))+tabs([['records','沟通记录'],['phones','联系方式']])+(tab==='phones'?panel('家长联系方式',table(['学生','家长电话'],db.students.map(s=>[esc(s.name),`<a href="tel:${esc(s.phone)}">${esc(s.phone)}</a>`]))):recordsPanel('contacts'));
views.activities=()=>head('班级活动',btn('导出 Excel',"exportData('activities')",'download')+btn('新增记录',"edit('activities')",'plus','primary'))+recordsPanel('activities');
views.todo=()=>head('待办 & 备忘录',btn('新建待办',"edit('todos')",'plus','primary'))+tabs([['todo','待办事项'],['notes','备忘录']])+(tab==='todo'?panel('每日待办',todoList()):panel('备忘录',`<div class="actions" style="margin-bottom:18px">${btn('新增笔记',"edit('notes')",'plus')}</div>${db.notes.map(n=>`<article><h3>${esc(n.title)}</h3><p class="record-content">${esc(n.content)}</p>${operations('notes',n.id)}<div class="divider"></div></article>`).join('')||empty()} `));
views.links=()=>head('常用网址',btn('添加网址',"edit('links')",'plus','primary'))+`<div class="card-grid">${db.links.map(l=>`<div class="panel"><span class="pill">${icon('link')}</span><h3 style="margin:20px 0">${esc(l.title)}</h3><div class="actions"><a class="btn primary" href="${esc(l.url)}" target="_blank" rel="noopener">打开网站 ↗</a>${operations('links',l.id)}</div></div>`).join('')}</div>`;
const petEmoji={cat:'🐱',dog:'🐶',rabbit:'🐰'},petNames={cat:'小猫',dog:'小狗',rabbit:'小兔子'};function level(s){return Math.min(100,1+Math.floor(s.xp/100))}
views.pets=()=>{let ts=tabs([['pets','我的宠物'],['shop','宠物商店'],['points','积分管理'],['records','奖惩记录'],['rank','成长排行'],['atlas','宠物图鉴']]);let content='';if(tab==='pets')content=searchBar()+`<div class="card-grid">${db.students.filter(s=>s.name.includes(query)).map(s=>`<section class="panel pet-card"><span class="pill" style="position:absolute;top:15px;right:15px">Lv.${level(s)}</span><div class="pet-emoji">${petEmoji[s.pet]}${s.decor||''}</div><div class="student">${esc(s.name)}</div><p class="muted" style="font-size:11px">${petNames[s.pet]} · ${s.points} 积分</p><div class="attributes">${[['成长',s.xp%100],['饱食',s.food],['心情',s.mood],['清洁',s.clean]].map(([k,v])=>`<div class="row" style="justify-content:space-between;margin-top:10px"><span>${k}</span><small>${v}/100</small></div><div class="mini-progress"><span style="width:${v}%"></span></div>`).join('')}</div><div class="actions" style="justify-content:center">${btn('喂养 · 5分',`petAction('${s.id}','feed')`,'','small')}${btn('清洁 · 3分',`petAction('${s.id}','clean')`,'','small')}${btn('换宠物',`choosePet('${s.id}')`,'','small')}</div></section>`).join('')}</div>`;else if(tab==='shop'){content=panel('选择学生',`<select onchange="petFilter=this.value;render()"><option value="">请选择学生</option>${db.students.map(s=>`<option value="${s.id}" ${petFilter===s.id?'selected':''}>${esc(s.name)} · ${s.points}分</option>`).join('')}</select>`)+`<div class="grid3">${[['feed','🍎','营养食物',5,'饱食 +20，成长 +20'],['toy','🧶','毛线玩具',8,'心情 +20，成长 +25'],['clean','🛁','泡泡浴',3,'清洁 +25，成长 +10'],['hat','🎩','小礼帽',20,'解锁帽子装扮'],['glasses','👓','圆框眼镜',20,'解锁眼镜装扮'],['scarf','🧣','暖暖围巾',20,'解锁围巾装扮']].map(([k,e,n,p,d])=>panel(n,`<div style="font-size:52px;margin:20px 0">${e}</div><p class="muted" style="font-size:12px">${d}</p>${btn(p+' 积分购买',`petAction(petFilter,'${k}')`,'shopping-bag','primary')}`)).join('')}</div>`}else if(tab==='points')content=panel('积分管理',`<form id="point-form" class="form-grid" onsubmit="event.preventDefault();addPoints()">${field(['student','学生','student'])}${field(['amount','积分变化','number'],5)}${field(['reason','奖惩原因','select',['考试进步','作业完成','遵守纪律','课堂表现','热心助人','违纪扣分','作业未交','其他']])}<label class="field"><span>加分 / 扣分</span><select name="direction"><option value="1">加分</option><option value="-1">扣分</option></select></label><div class="field full"><button class="btn primary">确认记分</button></div></form>`);else if(tab==='records')content=panel('奖惩明细',searchBar()+table(['日期','学生','原因','变动','余额'],db.points.filter(r=>(sn(r.student)+r.reason).includes(query)).slice().reverse().map(r=>[r.date,esc(sn(r.student)),esc(r.reason),`<span class="pill ${r.amount<0?'orange':''}">${r.amount>0?'+':''}${r.amount}</span>`,r.balance])));else if(tab==='rank')content=panel('成长排行',table(['排名','学生','伙伴','等级','积分'],db.students.slice().sort((a,b)=>level(b)-level(a)||b.points-a.points).map((s,i)=>[`<span class="rank">${i+1}</span>`,esc(s.name),petEmoji[s.pet],level(s),s.points])));else content=`<div class="grid3">${Object.entries(petEmoji).map(([k,e])=>panel(petNames[k],`<div class="pet-emoji" style="font-size:90px;text-align:center">${e}</div><p class="muted">${db.students.filter(s=>s.pet===k).length} 位学生的成长伙伴</p>`)).join('')}</div>`+panel('装扮图鉴','<div style="font-size:50px;display:flex;gap:40px">🎩 👓 🧣</div>');return head('成长乐园','',`${db.students.length} 个成长伙伴`)+ts+content};
function changePoints(s,amount,reason){s.points=Math.max(0,s.points+amount);db.points.push({id:uid(),student:s.id,date:today(),amount,reason,balance:s.points})}
function addPoints(){let fd=new FormData($('#point-form')),s=db.students.find(x=>x.id===fd.get('student'));if(!s)return;let a=Number(fd.get('amount'))*Number(fd.get('direction'));if(!Number.isFinite(a)||!Number.isInteger(a)||a===0){toast('请输入正整数积分');return}if(s.points+a<0){toast('积分不足，无法扣除');return}changePoints(s,a,fd.get('reason'));save();toast('积分已更新');render()}
function petAction(id,k){let s=db.students.find(s=>s.id===id);if(!s){toast('请先选择学生');return}let price={feed:5,toy:8,clean:3,hat:20,glasses:20,scarf:20}[k];if(s.points<price){toast('积分不足');return}changePoints(s,-price,'宠物消费 · '+({feed:'食物',toy:'玩具',clean:'清洁',hat:'帽子',glasses:'眼镜',scarf:'围巾'}[k]));if(k==='feed'){s.food=Math.min(100,s.food+20);s.xp=Math.min(9999,s.xp+20)}else if(k==='toy'){s.mood=Math.min(100,s.mood+20);s.xp=Math.min(9999,s.xp+25)}else if(k==='clean'){s.clean=Math.min(100,s.clean+25);s.xp=Math.min(9999,s.xp+10)}else{s.decor={hat:'🎩',glasses:'👓',scarf:'🧣'}[k]}save();render();toast('小伙伴收到啦')}
function choosePet(id){showModal('选择成长伙伴',`<div class="grid3">${Object.entries(petEmoji).map(([k,e])=>`<button class="panel" style="text-align:center" onclick="db.students.find(s=>s.id==='${id}').pet='${k}';save();closeModal();render()"><span style="font-size:65px">${e}</span><p>${petNames[k]}</p></button>`).join('')}</div>`)}
views.seats=()=>{let st=db.seat;return head('排座位',btn('导出图片',"seatImage()",'image-down')+btn('保存方案',"saveSeat()",'save','primary'))+`<div class="toolbar"><div class="actions"><label>行 <input id="seat-rows" aria-label="行数" type="number" min="1" max="12" value="${st.rows}" style="width:65px"></label><label>列 <input id="seat-cols" aria-label="列数" type="number" min="1" max="10" value="${st.cols}" style="width:65px"></label><label>过道在第 <input id="seat-aisle" aria-label="过道位置" type="number" min="0" max="10" value="${st.aisle}" style="width:60px"> 列后</label>${btn('应用',"applySeat()")}</div><div class="actions">${btn('学生属性',"go('students')",'sliders-horizontal')}${btn('一键排座',"autoSeat()",'shuffle','primary')}</div></div><div class="notice" style="margin-bottom:18px">点击两个座位交换位置；也可拖拽交换。自动排座按优先前三排、近视、身高排序。</div>${panel('班级座位表',`<div class="board">讲 台</div><div class="seat-grid" style="grid-template-columns:repeat(${st.cols},1fr)">${Array.from({length:st.rows*st.cols},(_,i)=>{let s=db.students.find(s=>s.id===st.ids[i]);return `<div tabindex="0" role="button" aria-label="第${i+1}座 ${s?esc(s.name):'空位'}" class="seat ${s?'':'empty'} ${i%st.cols+1===st.aisle?'aisle':''} ${selectedSeat===i?'selected':''}" draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${i}')" ondragover="event.preventDefault()" ondrop="event.preventDefault();swapSeat(Number(event.dataTransfer.getData('text/plain')),${i})" onclick="seatClick(${i})" onkeydown="if(event.key==='Enter')seatClick(${i})">${s?esc(s.name):'空位'}<small>${s?esc(s.number)+'号 · '+s.height+'cm':'第'+(i+1)+'座'}</small></div>`}).join('')}</div>`)}${panel('历史方案',db.seatHistory.length?table(['方案','保存日期','操作'],db.seatHistory.map(r=>[esc(r.title),r.date,btn('使用',`loadSeat('${r.id}')`,'rotate-ccw','small')+btn('删除',`db.seatHistory=db.seatHistory.filter(x=>x.id!=='${r.id}');save();render()`,'','small')])):empty('尚未保存方案'))}`};
function applySeat(){let rows=Number($('#seat-rows').value),cols=Number($('#seat-cols').value),aisle=Number($('#seat-aisle').value);if(!Number.isInteger(rows)||!Number.isInteger(cols)||rows<1||rows>12||cols<1||cols>10||aisle<0||aisle>cols){toast('请检查行列与过道设置');return}if(rows*cols<db.students.length){toast('座位数量少于学生人数');return}db.seat={...db.seat,rows,cols,aisle};save();render()}
function autoSeat(){if(db.seat.rows*db.seat.cols<db.students.length){toast('请先增加座位数量');return}db.seat.ids=db.students.slice().sort((a,b)=>Number(b.front)-Number(a.front)||Number(b.myopia)-Number(a.myopia)||a.height-b.height).map(s=>s.id);save();render();toast('已按学生属性排座')}
function swapSeat(a,b){if(!Number.isInteger(a)||a<0||a>=db.seat.rows*db.seat.cols)return;let ids=db.seat.ids;[ids[a],ids[b]]=[ids[b]||null,ids[a]||null];selectedSeat=null;save();render()}
function seatClick(i){if(selectedSeat===null){selectedSeat=i;render()}else swapSeat(selectedSeat,i)}
function saveSeat(){showModal('保存座位方案',`<form id="seat-save" onsubmit="event.preventDefault();db.seatHistory.push({id:uid(),title:this.title.value,date:today(),seat:JSON.parse(JSON.stringify(db.seat))});save();closeModal();render()"><label class="field"><span>方案名称</span><input name="title" required value="${today()} 座位方案"></label></form>`,`<button form="seat-save" class="btn primary">保存</button>`)}function loadSeat(id){db.seat=JSON.parse(JSON.stringify(db.seatHistory.find(h=>h.id===id).seat));db.seat.ids=db.seat.ids.map(id=>db.students.some(s=>s.id===id)?id:null);save();render()}
function seatImage(){let st=db.seat,c=document.createElement('canvas'),ctx=c.getContext('2d');c.width=st.cols*170+100;c.height=st.rows*100+200;ctx.fillStyle='#f7f5fc';ctx.fillRect(0,0,c.width,c.height);ctx.textAlign='center';ctx.fillStyle='#594780';ctx.font='bold 28px sans-serif';ctx.fillText(db.settings.className+' 座位表',c.width/2,47);ctx.fillStyle='#8666d7';ctx.fillRect(c.width/2-140,75,280,40);ctx.fillStyle='#fff';ctx.font='20px sans-serif';ctx.fillText('讲 台',c.width/2,102);st.ids.forEach((id,i)=>{if(i>=st.rows*st.cols)return;let s=db.students.find(s=>s.id===id),x=50+i%st.cols*170,y=155+Math.floor(i/st.cols)*100;ctx.fillStyle='#ece5fa';ctx.fillRect(x,y,145,75);ctx.fillStyle='#77618f';ctx.font='19px sans-serif';ctx.fillText(s?.name||'空位',x+72,y+43)});c.toBlob(b=>download(b,'座位表.png'))}
views.settings=()=>head('系统设置')+`<div class="setting-section">${panel('个人与班级',`<form id="settings-form" class="form-grid" onsubmit="event.preventDefault();settingsSave()">${field(['teacher','班主任姓名'],db.settings.teacher)}${field(['className','班级名称'],db.settings.className)}${field(['term','学期'],db.settings.term)}${field(['pass','及格分数','number'],db.settings.pass)}${field(['excellent','优秀分数','number'],db.settings.excellent)}<div class="field full"><button class="btn primary">保存设置</button></div></form>`)}${panel('数据保存','<p class="record-content">数据保存在当前浏览器，刷新后保留。更换设备时，请在数据管理中导出备份并恢复。</p><p class="record-content">当前版本未接入账号登录与云端同步。</p>')}</div>`;
function settingsSave(){let fd=new FormData($('#settings-form'));let pass=+fd.get('pass'),excellent=+fd.get('excellent');if(pass<0||excellent>100||pass>excellent||!fd.get('teacher').trim()||!fd.get('className').trim()){toast('请检查姓名、班级和分数设置');return}db.settings={teacher:fd.get('teacher').trim(),className:fd.get('className').trim(),term:fd.get('term'),pass,excellent};save();render();toast('设置已保存')}
views.data=()=>head('数据管理')+`<div class="grid3">${panel('导出备份','<p class="muted" style="font-size:12px;margin:20px 0">完整保存班级资料、照片与成长记录。</p>'+btn('导出全量备份',"backup()",'download','primary'))}${panel('恢复备份','<p class="muted" style="font-size:12px;margin:20px 0">从备份文件恢复，替换当前班级资料。</p>'+btn('选择备份文件',"restore()",'upload'))}${panel('班级资料','<p class="muted" style="font-size:12px;margin:20px 0">学生花名册与各模块数据独立导出。</p>'+btn('导出学生 Excel',"exportData('students')",'sheet'))}</div>`+panel('当前数据',table(['数据','数量'],[['学生',db.students.length],['考试',db.exams.length],['工作记录',db.work.length],['谈话记录',db.talks.length],['成长记分',db.points.length]]))+`<section class="panel danger-zone"><div class="panel-head"><h2>演示与重置</h2></div><div class="actions">${btn('重置演示数据',"resetDialog(false)",'rotate-ccw','danger')}${btn('清空并建立自己的班级',"resetDialog(true)",'trash-2','danger')}</div></section>`;
function resetDialog(clear){showModal('确认重置',`<p>${clear?'将清空所有演示及录入数据，建立空白班级。':'当前数据将被演示数据替换。'}请先备份需要保留的资料。</p>`,btn('取消','closeModal()')+btn('确认重置',`resetData(${clear})`,'','danger'))}
function resetData(clear){let settings={...db.settings};db=demo();if(clear){Object.keys(db).forEach(k=>{if(Array.isArray(db[k]))db[k]=[]});db.seat.ids=[];db.settings=settings}save();closeModal();render();toast('已重置')}
function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function backup(){download(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),'班主任工作台_备份_'+today()+'.json');toast('备份已导出')}
function pickFile(accept,cb){let f=$('#file');f.accept=accept;f.value='';f.onchange=async()=>{if(f.files[0])try{await cb(f.files[0])}catch(e){toast('文件读取失败：'+e.message)}};f.click()}
function restore(){pickFile('.json',async f=>{let r=JSON.parse(await f.text());if(r.version!==1||!r.settings||!r.seat||!Array.isArray(r.students)||!Array.isArray(r.exams)||['discipline','leaves','homework','work','talks','contacts','activities','todos','notes','links','points','seatHistory'].some(k=>!Array.isArray(r[k])))throw Error('不是有效的工作台备份');if(r.students.some(s=>!s.id||typeof s.name!=='string')||r.exams.some(e=>!Array.isArray(e.scores)))throw Error('备份结构损坏');window.pendingRestore=r;showModal('恢复备份',`<p>文件包含 ${r.students.length} 位学生，${r.work.length} 条工作记录。</p><p>恢复后将替换当前数据。</p>`,btn('取消','closeModal()')+btn('确认恢复',"db=window.pendingRestore;save();closeModal();render();toast('备份已恢复')",'','primary'))})}
// Native XLSX: UTF-8 XML parts in a standard ZIP package.
const te=new TextEncoder(),td=new TextDecoder();function xml(s){return esc(s)}
function crc32(a){let c=0xffffffff;for(let b of a){c^=b;for(let j=0;j<8;j++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^0xffffffff)>>>0}
function zip(files){let chunks=[],central=[],offset=0;for(let [name,data]of Object.entries(files)){let n=te.encode(name),d=typeof data==='string'?te.encode(data):data,crc=crc32(d);let h=new Uint8Array(30+n.length);let v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,d.length,true);v.setUint32(22,d.length,true);v.setUint16(26,n.length,true);h.set(n,30);chunks.push(h,d);let c=new Uint8Array(46+n.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,crc,true);cv.setUint32(20,d.length,true);cv.setUint32(24,d.length,true);cv.setUint16(28,n.length,true);cv.setUint32(42,offset,true);c.set(n,46);central.push(c);offset+=h.length+d.length}let end=new Uint8Array(22),v=new DataView(end.buffer),cs=central.reduce((n,c)=>n+c.length,0);v.setUint32(0,0x06054b50,true);v.setUint16(8,central.length,true);v.setUint16(10,central.length,true);v.setUint32(12,cs,true);v.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function cellName(n){let s='';for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s}
function makeXlsx(rows){let sheet=`<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${rows.map((r,i)=>`<row r="${i+1}">${r.map((v,j)=>`<c r="${cellName(j)}${i+1}" ${typeof v==='number'?'':'t="inlineStr"'}>${typeof v==='number'?`<v>${v}</v>`:`<is><t xml:space="preserve">${xml(v)}</t></is>`}</c>`).join('')}</row>`).join('')}</sheetData></worksheet>`;return zip({'[Content_Types].xml':'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>','_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml':'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="班级数据" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>','xl/worksheets/sheet1.xml':sheet})}
function dataRows(col){if(col==='scores'){let ex=latest();return [['学号','姓名',...subjects,'总分','排名'],...ranking(ex).map(r=>[db.students.find(s=>s.id===r.student)?.number||'',sn(r.student),...subjects.map(k=>r[k]),total(r),r.rank])]}if(col==='homework')return [['科目','作业标题','布置日期','截止日期','提交率','未交学生'],...db.homework.map(h=>[h.subject,h.title,h.date,h.deadline,percent(h)+'%',db.students.filter(s=>!h.submitted.includes(s.id)).map(s=>s.name).join('、')])];let schema=schemas[col].filter(s=>s[2]!=='file');return [schema.map(s=>s[1]),...db[col].map(r=>schema.map(([k,l,t])=>k==='student'?sn(r[k]):t==='check'?r[k]?'是':'否':r[k]??''))]}
function exportData(col){download(makeXlsx(dataRows(col)),(col==='scores'?'成绩':collectionNames[col])+'_'+today()+'.xlsx');toast('Excel 已导出')}
function template(col){let rows=col==='students'?[['学号','姓名','性别','家长电话','身高（cm）','近视','优先前三排','综合评价'],['01','示例同学','男','13800000000',160,'否','否','']]:[['学号','姓名',...subjects],...db.students.map(s=>[s.number,s.name,'','',''])];download(makeXlsx(rows),col==='students'?'学生导入模板.xlsx':'成绩录入模板.xlsx')}
async function unzip(buffer){let a=new Uint8Array(buffer),v=new DataView(buffer),pos=a.length-22;for(;pos>=Math.max(0,a.length-65558)&&v.getUint32(pos,true)!==0x06054b50;pos--);if(pos<0)throw Error('Excel 文件无效');let count=v.getUint16(pos+10,true),off=v.getUint32(pos+16,true),out={};for(let i=0;i<count;i++){if(v.getUint32(off,true)!==0x02014b50)throw Error('Excel 目录损坏');let method=v.getUint16(off+10,true),size=v.getUint32(off+20,true),nl=v.getUint16(off+28,true),el=v.getUint16(off+30,true),cl=v.getUint16(off+32,true),local=v.getUint32(off+42,true),name=td.decode(a.slice(off+46,off+46+nl));let start=local+30+v.getUint16(local+26,true)+v.getUint16(local+28,true),bytes=a.slice(start,start+size);if(method===8)bytes=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());else if(method!==0)throw Error('不支持的压缩格式');out[name]=td.decode(bytes);off+=46+nl+el+cl}return out}
function parseCsv(str){let rows=[],row=[],cell='',quote=false;for(let i=0;i<str.length;i++){let c=str[i];if(c==='"'){if(quote&&str[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&str[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
async function readRows(f){if(/\.csv$/i.test(f.name))return parseCsv((await f.text()).replace(/^\uFEFF/,''));let parts=await unzip(await f.arrayBuffer()),parser=new DOMParser,shared=parts['xl/sharedStrings.xml']?Array.from(parser.parseFromString(parts['xl/sharedStrings.xml'],'text/xml').getElementsByTagName('si')).map(n=>n.textContent):[];let sheet=Object.keys(parts).filter(k=>/^xl\/worksheets\/sheet\d+\.xml$/.test(k)).sort()[0];if(!sheet)throw Error('没有可读取的工作表');return Array.from(parser.parseFromString(parts[sheet],'text/xml').getElementsByTagName('row')).map(row=>{let arr=[];for(let cell of row.getElementsByTagName('c')){let ref=cell.getAttribute('r'),letters=ref.replace(/[0-9]/g,''),idx=0;for(let l of letters)idx=idx*26+l.charCodeAt(0)-64;let v=cell.getElementsByTagName('v')[0]?.textContent||'';let type=cell.getAttribute('t');arr[idx-1]=type==='s'?shared[+v]:type==='inlineStr'?cell.getElementsByTagName('is')[0]?.textContent||'':v}return arr})}
async function importData(col){pickFile('.xlsx,.csv',async f=>{let rows=await readRows(f);let headers=rows.shift().map(x=>String(x).trim());if(!headers.includes('学号')||!headers.includes('姓名'))throw Error('请使用含学号、姓名列的模板');let records=rows.filter(r=>r.some(x=>String(x||'').trim())).map(r=>Object.fromEntries(headers.map((h,i)=>[h,String(r[i]??'').trim()])));if(!records.length)throw Error('没有可导入的数据');if(col==='scores'&&subjects.some(k=>!headers.includes(k)))throw Error('缺少科目成绩列');let seen=new Set();for(let r of records){if(!r['学号']||!r['姓名'])throw Error('学号或姓名为空');if(seen.has(r['学号']))throw Error('文件中存在重复学号：'+r['学号']);seen.add(r['学号']);if(col==='scores'){let s=db.students.find(s=>s.number===r['学号']&&s.name===r['姓名']);if(!s)throw Error('学生未匹配：'+r['姓名']);if(subjects.some(k=>r[k]===''||!Number.isFinite(+r[k])||+r[k]<0||+r[k]>100))throw Error('成绩须为0–100：'+r['姓名'])}else if(r['性别']&&!['男','女'].includes(r['性别']))throw Error('性别须为男或女');}
window.pendingImport={col,records};showModal('确认导入',`<p>读取 ${records.length} 条${col==='students'?'学生':'成绩'}数据。</p><p>相同学号将更新，其余学生资料保留。</p>`,btn('取消','closeModal()')+btn('确认导入','applyImport()','','primary'))})}
function applyImport(){let {col,records}=window.pendingImport;if(col==='students'){for(let r of records){let s=db.students.find(s=>s.number===r['学号']);let values={number:r['学号'],name:r['姓名'],gender:r['性别']||'男',phone:r['家长电话']||'',height:Number(r['身高（cm）'])||160,myopia:r['近视']==='是',front:r['优先前三排']==='是',evaluation:r['综合评价']||''};if(s)Object.assign(s,values);else db.students.push({id:uid(),...values,pet:'cat',points:0,xp:0,food:80,mood:80,clean:80,decor:''})}}else{let ex=latest();if(!ex){toast('请先创建考试');return}records.forEach(r=>{let id=db.students.find(s=>s.number===r['学号']&&s.name===r['姓名']).id;let v={student:id,...Object.fromEntries(subjects.map(k=>[k,+r[k]]))};let old=ex.scores.find(s=>s.student===id);if(old)Object.assign(old,v);else ex.scores.push(v)})}save();closeModal();render();toast('导入成功')}
async function wordFile(title,sections){let children=[new docx.Paragraph({text:title,heading:docx.HeadingLevel.TITLE}),new docx.Paragraph({text:db.settings.className+' · '+db.settings.teacher+' · '+today()})];for(let section of sections){children.push(new docx.Paragraph({text:section.title,heading:docx.HeadingLevel.HEADING_1}));for(let line of section.lines)children.push(new docx.Paragraph({text:String(line)}));if(section.photo){let bytes=Uint8Array.from(atob(section.photo.split(',')[1]),c=>c.charCodeAt(0));children.push(new docx.Paragraph({children:[new docx.ImageRun({type:'jpg',data:bytes,transformation:{width:400,height:260}})]}))}}let doc=new docx.Document({sections:[{children}]});download(await docx.Packer.toBlob(doc),title+'.docx');toast('Word 已导出')}
function sectionsFor(col,rs){return rs.map(r=>({title:r.title||sn(r.student)+' · '+(r.date||''),lines:schemas[col].filter(x=>x[2]!=='file').map(([k,l])=>l+'：'+(k==='student'?sn(r[k]):r[k]||'—')),photo:r.photo}))}
function wordRecord(col,id){wordFile(collectionNames[col]+'_'+(db[col].find(r=>r.id===id)?.date||today()),sectionsFor(col,db[col].filter(r=>r.id===id)))}function wordAll(col){wordFile(collectionNames[col]+'汇总',sectionsFor(col,db[col]))}function wordFiltered(col){if(!filterStudent){toast('请先在列表中筛选学生');return}wordFile(sn(filterStudent)+'_'+collectionNames[col],sectionsFor(col,db[col].filter(r=>r.student===filterStudent)))}
function studentWord(id){let s=db.students.find(s=>s.id===id);let sections=[{title:'基本资料',lines:['姓名：'+s.name,'学号：'+s.number,'性别：'+s.gender,'家长电话：'+s.phone]},{title:'成绩概览',lines:db.exams.map(e=>{let r=e.scores.find(r=>r.student===id);return e.title+'：'+(r?subjects.map(k=>k+' '+r[k]).join('；')+'；总分 '+total(r):'暂无成绩')})},{title:'作业完成',lines:db.homework.map(h=>h.subject+' · '+h.title+'：'+(h.submitted.includes(id)?'已提交':'未提交'))},...['leaves','discipline','talks'].flatMap(col=>sectionsFor(col,db[col].filter(r=>r.student===id))),{title:'综合评价',lines:[s.evaluation||'暂无评价']}];wordFile(s.name+'_学生个人报告',sections)}
