let calendarOffset=0;
function calendarCard(){let base=new Date(today()+'T12:00:00');base.setMonth(base.getMonth()+calendarOffset,1);let year=base.getFullYear(),month=base.getMonth(),days=new Date(year,month+1,0).getDate(),first=(base.getDay()+6)%7,prevDays=new Date(year,month,0).getDate();let cells=Array.from({length:42},(_,i)=>{let day=i-first+1,other=day<1||day>days,label=day<1?prevDays+day:day>days?day-days:day;let iso=year+'-'+String(month+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');let active=!other&&iso===today(),has=!other&&db.todos.some(t=>!t.done&&t.date===iso);return `<span class="cal-day ${other?'other':''} ${active?'current':''} ${has?'has-event':''}">${label}</span>`});return `<section class="panel calendar-panel"><div class="calendar-top"><button class="icon" aria-label="上个月" onclick="calendarOffset--;renderContent()">${icon('chevron-left')}</button><strong>${year}年${month+1}月</strong><button class="icon" aria-label="下个月" onclick="calendarOffset++;renderContent()">${icon('chevron-right')}</button></div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(x=>`<small>周${x}</small>`).join('')}${cells.join('')}</div></section>`}
