views.dashboard=()=>{let ex=latest(),d=new Date(),m=today().slice(0,7),week=new Date(today()+'T12:00:00');week.setDate(week.getDate()-((week.getDay()+6)%7));let missing=db.homework.reduce((n,h)=>n+db.students.filter(s=>!h.submitted.includes(s.id)).length,0),pending=db.todos.filter(t=>!t.done).sort((a,b)=>a.date.localeCompare(b.date)),recent=pending.slice(0,4);return head('我的工作台',btn('新建待办',"edit('todos')",'plus','primary'),`${esc(db.settings.className)}　·　${d.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long',timeZone:'Asia/Shanghai'})}`)+`<div class="dashboard-layout"><div class="dashboard-primary"><div class="hero"><div class="hero-copy"><span class="hero-overline">${esc(db.settings.term)}</span><h2>${esc(db.settings.teacher)}，欢迎回来</h2><p>今天有 ${pending.filter(t=>t.date<=today()).length} 项待办，${db.leaves.filter(l=>l.status==='待审批').length} 条请假待审批</p>${btn('查看今日待办',"go('todo')",'arrow-up-right','hero-button')}</div><div class="hero-illustration">${classroomArt}</div></div><div class="quick">${[['leaves','calendar-plus','记请假'],['homework','notebook-pen','记作业'],['discipline','shield-alert','记违纪'],['work','folder-plus','记工作'],['students','users-round','学生管理']].map(([k,i,l])=>`<button onclick="${k==='students'?"go('students')":`edit('${k}')`}"><span>${icon(i)}</span>${l}</button>`).join('')}</div><div class="section-heading"><h2>班级概况</h2><small>${db.students.length} 位学生</small></div><div class="stats">${stat('班级人数',db.students.length,`男 ${db.students.filter(s=>s.gender==='男').length} · 女 ${db.students.filter(s=>s.gender==='女').length}`,'users-round')}${stat('今日请假',db.leaves.filter(x=>x.date<=today()&&x.end>=today()&&x.status==='已批准').length,'已批准','calendar-clock')}${stat('作业未交',missing,'待提交人次','notebook-pen')}${stat('本周违纪',db.discipline.filter(x=>x.date>=week.toLocaleDateString('sv-SE')&&x.date<=today()).length,'本周累计','shield-alert')}${stat('本月留痕',db.work.filter(x=>x.date.startsWith(m)).length,'工作记录','folder-open')}${stat('待办事项',pending.length,`${pending.filter(x=>x.important).length} 项重要`,'list-checks')}</div><div class="grid2 dashboard-analysis">${panel('各科平均分',`<small>${esc(ex?.title||'暂无考试')}</small>${bars(subjects.map(s=>[s,avg(ex,s)]))}`,`<button class="link-btn" onclick="go('grades','analysis')">查看全部 →</button>`)}${panel('作业完成情况',db.homework.slice(0,3).map(h=>`<div class="homework-row"><div class="row"><span><span class="subject-tag">${esc(h.subject)}</span>${esc(h.title)}</span><b>${percent(h)}%</b></div><div class="mini-progress"><span style="width:${percent(h)}%"></span></div></div>`).join('')||empty(),`<button class="link-btn" onclick="go('homework')">查看全部 →</button>`)}</div>${panel('最近工作',db.work.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(w=>`<div class="reminder"><span class="work-icon">${icon('folder-open')}</span><div class="text"><strong>${esc(w.title)}</strong><small>${w.date} · ${esc(w.type)}</small></div>${btn('查看',`detail('work','${w.id}')`,'','small')}</div>`).join('')||empty())}</div><div class="dashboard-rail">${calendarCard()}${panel('近期提醒',recent.map(r=>`<div class="schedule-row"><span class="schedule-date">${r.date.slice(5).replace('-','/')}</span><div class="schedule-card ${r.important?'important':''}"><strong>${esc(r.title)}</strong><div><small>${r.date<today()?'已逾期':r.date===today()?'今天':r.date}</small>${r.important?'<span>重要</span>':''}</div></div></div>`).join('')||empty(),`<button class="round-add" aria-label="添加提醒" onclick="edit('todos')">${icon('plus')}</button>`)}${panel('今日待办',todoList(4),`<button class="link-btn" onclick="go('todo')">全部 →</button>`)}<section class="panel rail-pet"><div class="row"><span class="pet-bubble">🐱</span><div><h3>成长乐园</h3><small>${db.students.length} 只成长伙伴</small></div></div><button class="btn" onclick="go('pets')">查看成长记录 ${icon('arrow-up-right')}</button></section></div></div>`};
